async function chooseView(page:Page,view:CategoryViewMode,route:string){const control=page.locator('[data-category-page-action="switch-view"][data-category-page-category="'+route+'"][data-category-page-view="'+view+'"]');await activate(page,control);await expect(control).toHaveAttribute('aria-selected','true');await expect(control).toHaveAttribute('tabindex','0');}
async function chooseRange(page:Page,mode:CategoryRangeMode){
 const header=page.locator('#header-range-toggle [data-range="'+mode+'"]');
 if(await header.isVisible()){
  if(await header.getAttribute('aria-pressed')!=='true')await activate(page,header);
  await expect(header).toHaveAttribute('aria-pressed','true');
 }else{
  // Native mobile CSS hides the header range toolbar; Settings exposes the
  // same switchRangeMode callback through its visible Display controls.
  await activate(page,page.getByRole('button',{name:'Settings',exact:true}));
  const overlay=page.locator('#settings-modal-overlay');await expect(overlay).toBeVisible();
  const display=overlay.locator('[data-settings-tab="display"]');await activate(page,display);await expect(display).toHaveAttribute('aria-selected','true');
  const control=overlay.locator('[data-settings-action="switch-range"][data-range="'+mode+'"]');await expect(control).toBeVisible();
  if(await control.getAttribute('aria-pressed')!=='true')await activate(page,control);
  await expect(control).toHaveAttribute('aria-pressed','true');
  await activate(page,overlay.locator('[data-settings-action="close"]'));await expect(overlay).toBeHidden();
 }
 expect(await page.evaluate(()=>localStorage.getItem('labcharts-default-rangeMode'))).toBe(mode);
}
