async function categoryChromeLayout(page:Page){
 return page.locator('#main-content').evaluate(root=>{
  const styles=(selector:string,properties:string[])=>{const element=root.querySelector<HTMLElement>(selector);if(!element)return null;const css=getComputedStyle(element),rect=element.getBoundingClientRect();return {properties:Object.fromEntries(properties.map(property=>[property,css.getPropertyValue(property)])),rectangle:{x:rect.x,y:rect.y,width:rect.width,height:rect.height,right:rect.right,bottom:rect.bottom}};};
  const probe=document.createElement('span');probe.style.color='var(--text-secondary)';probe.hidden=true;root.append(probe);const secondary=getComputedStyle(probe).color;probe.style.color='var(--text-muted)';const muted=getComputedStyle(probe).color;probe.remove();
  return {viewport:{width:innerWidth,height:innerHeight},theme:document.documentElement.dataset.theme||'dark',secondary,muted,title:styles('.category-title-text',['min-width']),header:styles('.category-header h2',['font-size','display','align-items','gap']),tabs:styles('.view-toggle',['display','gap','padding','margin-bottom']),body:styles('#view-content',['min-width']),gapSection:styles('.chart-card-gap-section',['margin-top']),gapHeading:styles('.chart-card-gap-section > p',['font-size','margin-bottom','color']),gapList:styles('.chart-card-gap-list',['display','flex-wrap','gap']),gapButton:styles('.chart-card-add',['display','flex-direction','align-items','text-align']),gapName:styles('.chart-card-add > span:first-child',['color']),gapSuffix:styles('.chart-card-add > span:last-child',['color','font-size','margin-left']),emptyIcon:styles('.empty-state-icon-category',['display','justify-content'])};
 });
}
function assertCategoryChromeLayout(actual:Awaited<ReturnType<typeof categoryChromeLayout>>){
 expect(actual.title?.properties).toEqual({'min-width':'0px'});
 expect(actual.header?.properties).toEqual({'font-size':actual.viewport.width<=480?'20px':'24px',display:'flex','align-items':'center',gap:'10px'});
 expect(actual.tabs?.properties).toEqual({display:'flex',gap:'4px',padding:'3px','margin-bottom':'0px'});
 expect(actual.body?.properties).toEqual({'min-width':'0px'});
 for(const box of [actual.header,actual.tabs,actual.body]){expect(box?.rectangle.width).toBeGreaterThan(0);expect(box?.rectangle.height).toBeGreaterThan(0);}
 if(actual.gapSection){expect(actual.gapSection.properties).toEqual({'margin-top':'16px'});expect(actual.gapHeading?.properties).toEqual({'font-size':'13px','margin-bottom':'8px',color:actual.secondary});expect(actual.gapList?.properties).toEqual({display:'flex','flex-wrap':'wrap',gap:'8px'});expect(actual.gapButton?.properties).toEqual({display:'flex','flex-direction':'row','align-items':'center','text-align':'left'});expect(actual.gapName?.properties).toEqual({color:actual.secondary});expect(actual.gapSuffix?.properties).toEqual({color:actual.muted,'font-size':'11px','margin-left':'6px'});}
 if(actual.emptyIcon)expect(actual.emptyIcon.properties).toEqual({display:'flex','justify-content':'center'});
}

